"""Stage an official same-version portable x64 muxer; no executable is run."""
from pathlib import Path
import hashlib,json,shutil,uuid,argparse
from driver import ps,q
ROOT=Path(__file__).resolve().parents[2]
p=argparse.ArgumentParser();p.add_argument('manifest',type=Path);a=p.parse_args()
m=a.manifest.resolve();meta=json.loads(m.read_text());assert m.parent.name=='c14baa31227d4c4b9a391aba4d1fe4bc'
assert meta['owner']=='connection' and meta['runtime']=='win-x64' and meta['buildExitCode']==0
host=ROOT/'artifacts/replica/workers/connection/official-host-10.0.12-win-x64';identity=json.loads((host/'identity.json').read_text());assert identity['peMachine']=='0x8664'
archive=host/'runtime.zip';assert hashlib.sha512(archive.read_bytes()).hexdigest()==identity['zipSHA512']
nonce=uuid.uuid4().hex;folder='DBMV-Connection-OfficialHost-10.0.12-win-x64-'+nonce
