stage=json.loads((m.parent/'windows-stage.json').read_text());binary=Path(meta['binary']);files={str(f.relative_to(binary.parent)).replace('/','\\'):hashlib.sha256(f.read_bytes()).hexdigest() for f in binary.parent.rglob('*') if f.is_file()}
manifest=ROOT/'artifacts/replica/windows-download'/('connection-fullflow-official-host-'+nonce+'-files.json');manifest.write_text(json.dumps(files));manifestSha=hashlib.sha256(manifest.read_bytes()).hexdigest()
code="$ProgressPreference='SilentlyContinue';$folder=Join-Path $env:TEMP "+q(folder)+";if(Test-Path $folder){throw 'New owner-specific muxer folder required'};New-Item -ItemType Directory $folder|Out-Null;$zip=Join-Path $folder 'official.zip';Invoke-WebRequest -UseBasicParsing "+q('http://10.211.55.2:8768/'+served.name)+" -OutFile $zip;if((Get-FileHash $zip -Algorithm SHA512).Hash-ne "+q(identity['zipSHA512'].upper())+"){throw 'Microsoft official ZIP SHA512'};Expand-Archive -LiteralPath $zip -DestinationPath $folder;Remove-Item $zip;$exe=[IO.Path]::GetFullPath((Join-Path $folder 'dotnet.exe'));$bytes=[IO.File]::ReadAllBytes($exe);$offset=[BitConverter]::ToInt32($bytes,60);if([BitConverter]::ToUInt16($bytes,$offset+4)-ne0x8664){throw 'Official muxer must be x64'};if((Get-FileHash $exe -Algorithm SHA256).Hash-ne "+q(identity['dotnetSHA256'].upper())+"){throw 'Exact official muxer SHA'};$fxr=Join-Path $folder 'host\\fxr\\10.0.12\\hostfxr.dll';if((Get-FileHash $fxr -Algorithm SHA256).Hash-ne "+q(identity['hostfxrSHA256'].upper())+"){throw 'Same-version official hostfxr'};"
code+="$f=Join-Path $folder 'frozen-files.json';Invoke-WebRequest -UseBasicParsing "+q('http://10.211.55.2:8768/'+manifest.name)+" -OutFile $f;if((Get-FileHash $f -Algorithm SHA256).Hash-ne "+q(manifestSha.upper())+"){throw 'Frozen file manifest SHA'};$app=[IO.Path]::GetFullPath((Join-Path (Join-Path $env:TEMP "+q(stage['guestFolder'])+") 'app'));$captured=[IO.File]::ReadAllText($f)|ConvertFrom-Json;foreach($file in $captured.PSObject.Properties){$path=Join-Path $app $file.Name;if(!(Test-Path $path)-or(Get-FileHash $path -Algorithm SHA256).Hash-ne$file.Value){throw ('Frozen current dep mismatch '+$file.Name)}};[pscustomobject]@{scope='Project-only staging and official identity/currentdeps verification, no executable/window/input';path=$exe;hostSHA256=(Get-FileHash $exe -Algorithm SHA256).Hash;hostfxrSHA256=(Get-FileHash $fxr -Algorithm SHA256).Hash;peMachine='0x8664';fileVersion=(Get-Item $exe).VersionInfo.FileVersion;app=$app;dll=(Join-Path $app 'ReplicaProbe.dll');dllSHA256=(Get-FileHash(Join-Path $app 'ReplicaProbe.dll') -Algorithm SHA256).Hash;frozenFileCount=@($captured.PSObject.Properties).Count;frozenFilesManifestSHA256="+q(manifestSha)+";observedUtc=[DateTime]::UtcNow.ToString('O')}|ConvertTo-Json -Compress;"
r=ps(code,timeout=40);out=m.parent/'actual-fullflow-windows';(out/'official-host-stage.json').write_text(r+'\n');print(r)
